async function importTemplate(url){if(confirm("This will create a new journey map in your account. Continue?")){"function"==typeof toggleLoading&&toggleLoading(!0);try{const fetchUrl=url.startsWith("/")?url:"/"+url,response=await fetch(fetchUrl);if(!response.ok)throw new Error(`Failed to download template file (${response.status} ${response.statusText})`);const data=await response.json();if(!data.stages||!data.swimlanes)throw new Error("Invalid OpenJourney format: stages or swimlanes are missing.");const generateUID=()=>"undefined"!=typeof crypto&&"function"==typeof crypto.randomUUID?crypto.randomUUID():"xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g,function(c){const r=16*Math.random()|0;return("x"===c?r:3&r|8).toString(16)}),usedIds=new Set;Array.isArray(data.nodes)&&(data.nodes=data.nodes.map(node=>(node.id&&!usedIds.has(node.id)||(node.id="n-"+generateUID()),usedIds.add(node.id),node)));const formattedTitle=url.split("/").pop().replace(".ojf","").replace(/-/g," ").replace(/\b\w/g,l=>l.toUpperCase()),saveResponse=await fetch("/api/journeys.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({title:`Template: ${formattedTitle}`,description:"Imported from sample library.",journey_status:"active",ojf_data:data})});if(!saveResponse.ok){const errData=await saveResponse.json().catch(()=>({}));throw new Error(errData.error||`Server error (${saveResponse.status}) while saving template`)}const record=await saveResponse.json();if(!record||!record.id)throw new Error("Server returned an invalid journey record.");alert("Template imported successfully!"),window.location.href=`/journey/${record.id}/`}catch(err){console.error("Template import error:",err),alert("Failed to import template: "+err.message),window.dataLayer&&window.dataLayer.push({event:"app_error",error_context:"import_template",error_message:err.message})}finally{"function"==typeof toggleLoading&&toggleLoading(!1)}}}window.importTemplate=importTemplate;